def cite(refs):
    return CITES.get(refs[0]) if refs else None


def row(cid, line_stage, therapy_type, name, drugs, stage, refs, uur, udd,
        section="3 (Приложение А3.2)", table=None, special="", maint=None,
        ecog=None, biomarkers=None):
    return {
        "cohort_id": cid,
        "disease": DISEASE,
        "treatment": {"line_stage": line_stage, "therapy_type": therapy_type, "regimen_name": name},
        "drugs": drugs,
        "indications": {"stage": stage, "ecog": ecog, "biomarkers": biomarkers or []},
        "evidence": {"uur": uur, "udd": udd},
        "source": {"page": None, "section": section, "table": table,
                   "references": refs, "citation": cite(refs)},
        "special_conditions": special,
        "maintenance_therapy": maint,
    }


